using UnityEngine; using UnityEditor; public class RemoveMissingScripts { [MenuItem("Tools/Remove Missing Scripts In Match Scene")] public static void CleanUp() { UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/Match.unity"); int count = 0; foreach (var go in Resources.FindObjectsOfTypeAll<GameObject>()) { count += GameObjectUtility.RemoveMonoBehavioursWithMissingScript(go); } Debug.Log($"Removed {count} missing scripts"); UnityEditor.SceneManagement.EditorSceneManager.SaveOpenScenes(); } }
